import sys
max = sys.maxsize

vertices_number = 6
adjacency_matrix = [
    [0, 1, 10, -1, -1, 2],
    [10, 0, 1, -1, -1, -1],
    [1, 10, 0, -1, -1, -1],
    [-1, -1, 2, 0, 1, 10],
    [-1, -1, -1, 10, 0, 1],
    [-1, -1, -1, 1, 10, 0]]
start = []
dest = ["2", "5"]
key = []

def init_keys(s: int):
    global key
    key = [ max ] * vertices_number
    key[s] = 0

def dijkstra(from_vertex, dest_vertex):
    fid = int(from_vertex) - 1
    tid = int(dest_vertex) - 1
    init_keys(fid)
    rel = [fid]
    min_vertex = fid
    hop_path = {}

    while len(rel) <= vertices_number and min_vertex != tid:
        for i in range(vertices_number):
            if i != min_vertex and i not in rel and \
                adjacency_matrix[min_vertex][i] > 0 \
                and key[i] > key[min_vertex] + adjacency_matrix[min_vertex][i]:
                key[i] = key[min_vertex] + adjacency_matrix[min_vertex][i]
                hop_path.update({i + 1: {"from": min_vertex + 1, "cost": adjacency_matrix[min_vertex][i]}})

        if min_vertex not in rel:
            rel.append(min_vertex)

        min_vertex = tid
        for i in range(vertices_number):
            if i not in rel and key[i] < key[min_vertex]:
                min_vertex = i

    if len(hop_path) == 0 or int(dest_vertex) not in hop_path:
        return -1, -1
    else:
        next_hop = int(dest_vertex)
        path_str = dest_vertex
        while hop_path[next_hop]["from"] != int(from_vertex):
            cost = hop_path[next_hop]["cost"]
            next_hop = hop_path[next_hop]["from"]
            path_str =  "{} -({})-> {}".format(str(next_hop), cost ,path_str)
        path_str =  "{} -({})-> {}".format(str(hop_path[next_hop]["from"]), hop_path[next_hop]["cost"], path_str)

        return key[tid], path_str

def find_shortest_router():
    for s in start:
        print("Forwarding Table for {}".format(s))
        print("{:>10} {:>10}       {}".format("To", "Cost", "Path"))
        for d in dest:
            c, n = dijkstra(s, d)
            print("{:>10} {:>10}       {}".format(d, c, n))

def main():
    for i in range(1, vertices_number + 1):
        if str(i) not in dest:
            start.append(str(i))
    find_shortest_router()

if __name__ == '__main__':
    main()

拉盖尔函数可以由合流超几何函数和Kummer变换得到： L_n^{(\alpha)}(x):= {n+ \alpha \choose n} M(-n,\alpha+1,x)={n+ \alpha \choose n} \sum_{i=0} (-1)^i \frac{{n \choose i}}{{\alpha+i \choose i}}x^i\, = e^x\cdot {n+ \alpha \choose n} M(\alpha+n+1,\alpha+1,-x)=\frac{e^x \sin(n \pi )}{\sin((n+\alpha)\pi)}L_{-\alpha-n-1}^{(\alpha)}(-x)=e^x\cdot\sum_{i=0}(-1)^i {\alpha+n+i \choose n} \frac{x^i}{i!}.当n为整数时，截断为n阶拉盖尔多项式。

n阶拉盖尔多项式可以通过将莱布尼茨乘积求导公式应用在罗德里格公式上而得到，结果为L_n^{(\alpha)} (x) = \sum_{i=0}^n (-1)^i {n+\alpha \choose n-i} \frac{x^i}{i!}。

n阶拉盖尔多项式的首项系数为(−1)n/n!；

拉盖尔多项式在x=0的取值（常数项）为 L_n^{(\alpha)}(0)= {n+\alpha\choose n} \approx \frac{n^\alpha}{\Gamma(\alpha+1)};

Ln(α)有n个实的正根（应该注意到 \left((-1)^{n-i} L_{n-i}^{(\alpha)}\right)_{i=0}^n构成以施图姆序列），且这些根全部位于区间(0, n+\alpha+ (n-1) \sqrt{n+\alpha}]中。

当n很大，而\alpha不变，x>0时，拉盖尔多项式的渐近行为如下：

L_n^{(\alpha)}(x) \approx \frac{n^{\frac{\alpha}{2}-\frac{1}{4}}}{\sqrt{\pi}} \frac{e^{\frac{x}{2}}}{x^{\frac{\alpha}{2}+\frac{1}{4}}} \cos\left(2 \sqrt{x \left(n+\frac{\alpha+1}{2}\right)}- \frac{\pi}{2}\left(\alpha+\frac{1}{2} \right) \right)，以及

L_n^{(\alpha)}(-x) \approx \frac{n^{\frac{\alpha}{2}-\frac{1}{4}}}{2\sqrt{\pi}} \frac{e^{-\frac{x}{2}}}{x^{\frac{\alpha}{2}+\frac{1}{4}}} \exp\left(2 \sqrt{x \left(n+\frac{\alpha+1}{2}\right)} \right)。

前几个广义拉盖尔多项式为：

L_0^{(\alpha)} (x) = 1

L_1^{(\alpha)}(x) = -x + \alpha +1

L_2^{(\alpha)}(x) = \frac{x^2}{2} - (\alpha + 2)x + \frac{(\alpha+2)(\alpha+1)}{2}

L_3^{(\alpha)}(x) = \frac{-x^3}{6} + \frac{(\alpha+3)x^2}{2} - \frac{(\alpha+2)(\alpha+3)x}{2}
+ \frac{(\alpha+1)(\alpha+2)(\alpha+3)}{6}

