class Edge(object):
    def __init__(self, u, v, w):
        self.source = u
        self.sink = v  
        self.capacity = w
    def __repr__(self):
        return "%s->%s:%s" % (self.source, self.sink, self.capacity)

class FlowNetwork(object):
    def __init__(self):
        self.adj = {}
        self.flow = {}

    def add_vertex(self, vertex):
        self.adj[vertex] = []

    def get_edges(self, v):
        return self.adj[v]

    def add_edge(self, u, v, w=0):
        if u == v:
            raise ValueError("u == v")
        edge = Edge(u,v,w)
        redge = Edge(v,u,0)
        edge.redge = redge
        redge.redge = edge
        self.adj[u].append(edge)
        self.adj[v].append(redge)
        self.flow[edge] = 0
        self.flow[redge] = 0

    def find_path(self, source, sink, path):
        if source == sink:
            return path
        for edge in self.get_edges(source):
            residual = edge.capacity - self.flow[edge]
            if residual > 0 and edge not in path:
                result = self.find_path( edge.sink, sink, path + [edge]) 
                if result != None:
                    return result

    def max_flow(self, source, sink):
        path = self.find_path(source, sink, [])
        while path != None:
            residuals = [edge.capacity - self.flow[edge] for edge in path]
            flow = min(residuals)
            for edge in path:
                self.flow[edge] += flow
                self.flow[edge.redge] -= flow
            path = self.find_path(source, sink, [])
        return sum(self.flow[edge] for edge in self.get_edges(source))

对于一串数字序列讯号x_0,x_1,...,x_{N-1}，定义它的离散傅立叶转换是：

y_m=\frac{1}{\sqrt{N}}\sum_{n=0}^{N-1} x_ne^{-\frac{2\pi mni}{N}} ,m=0,1,...,N-1

引入矩阵符号

X=\begin{bmatrix}
x_0 \\
x_1 \\
\vdots \\
x_{N-1}
\end{bmatrix}
\quad Y=\begin{bmatrix}
y_0 \\
y_1 \\
\vdots \\
y_{N-1}
\end{bmatrix}

E=\frac{1}{\sqrt{N}}\begin{bmatrix}
W^{0 \times 0} & W^{0 \times 1} & \vdots & W^{0 \times N-1} \\
W^{1 \times 0} & W^{1 \times 1} & \vdots & W^{1 \times N-1} \\
\vdots & \vdots & \ddots & \vdots \\
W^{N-1 \times 0} & W^{N-1 \times 1} & \vdots & W^{N-1 \times N-1} \\
\end{bmatrix}

其中 W=e^{-\frac{\pi 2i}{\sqrt{N}}} ，现在可以把离散傅立叶转换写成： Y=EX

由上面的分析可知一串长度为N的数字序列讯号x_0,x_1,...,x_{N-1}，其离散傅立叶转换在N维向量空间相当于一个线性转换，也就是矩阵E，矩阵E称作离散傅立叶转换的矩阵。又因为

\frac{1}{N}\sum_{l=0}^{N-1}W^{l \times m} \times \overline{W}^{l \times n}=\frac{1}{N}\sum_{l=0}^{N-1}e^{-\frac{2\pi li}{N} (m-n)}=
\begin{cases}
1 \quad m=n \\
0 \quad m \ne n
\end{cases}

所以 EE^*=I

离散傅立叶转换的线性转换是正交转换。

为了得到离散傅立叶转换的周期性定理，必须理解它的运算性质，因此现在用另外一个观点去说明4周期性质。

U=E^3X=E \times E^2X

=\begin{bmatrix}
W^{0 \times 0} & W^{0 \times 1} & \vdots & W^{0 \times N-1} \\
W^{1 \times 0} & W^{1 \times 1} & \vdots & W^{1 \times N-1} \\
\vdots & \vdots & \ddots & \vdots \\
W^{N-1 \times 0} & W^{N-1 \times 1} & \vdots & W^{N-1 \times N-1} \\
\end{bmatrix}
\begin{bmatrix}
1 & 0 & \vdots & 0 \\
0 & 0 & \vdots & 1 \\
\vdots & \vdots & \ddots & \vdots \\
0 & 1 & \vdots & 0
\end{bmatrix}
\begin{bmatrix}
x_0 \\
x_1 \\
\vdots \\
x_{N-1}
\end{bmatrix}

=\begin{bmatrix}
W^{0 \times 0} & W^{0 \times 1} & \vdots & W^{0 \times N-1} \\
W^{1 \times 0} & W^{1 \times 1} & \vdots & W^{1 \times N-1} \\
\vdots & \vdots & \ddots & \vdots \\
W^{N-1 \times 0} & W^{N-1 \times 1} & \vdots & W^{N-1 \times N-1} \\
\end{bmatrix}
\begin{bmatrix}
