\implies
\frac{\Gamma\left(\alpha\right)}{\lambda^\alpha}
=
\int_{0}^{\infty}
x^{\alpha-1}\mathrm{e}^{-\lambda x} {\rm{d}}x

使用Ruby实现的伫列，一个先进先出资料结构:

class Queue
  def initialize
    @input = []
    @output = []
  end

  def enqueue(element)
    @input << element
  end

  def dequeue
    if @output.empty?
      while @input.any?
        @output << @input.pop
      end
    end

    @output.pop
  end
end

伫列操作及特性参考伫列条目，enqeue及deqeue操作时间复杂度为常数， 否则，dequeue需要〔模板待展开：tmath〕时间将所有元素从输入数组添加到输出数组中，其中n是输入数组的当前长度。 从输入复制n元素后，我们可以在输出数组再次为空之前执行n出队操作，每次操作都需要一个恒定的时间。 因此，我们可以仅在〔模板待展开：tmath〕时间执行一系列n出列操作，这意味著每个出列操作的摊销时间是〔模板待展开：tmath〕 。

或者，我们可以收取将任何项目从输入数组复制到输出数组的成本，以及该项目的早期排队操作。 该计费方案将入队的摊还时间加倍，但将出列的摊还时间减少到〔模板待展开：tmath〕。

轮换一是种特殊的置换。

如果给定f:X\rightarrow X是X上的一个置换，A为X上的一个子集。

若有

\exists A\subset X,A=\{x_1,x_2,\cdots,x_l\}

\begin{cases} f(x_1)=x_2,f(x_2)=x_3,\cdots,f(x_l)=x_1 \\ f(x)=x,x\not\in A \end{cases}

则称f 为一个轮换。l 为轮换的长度。

#include <iostream>
using namespace std;
bool arrsame(int* arr, int len, int num) {
	int i;
	for (i = 0; i < len; i++)
		if (arr[i] == num)
			break;
	return i != len;
}
bool next_perm(int* perm, const int k, const int n) {
	int i = k - 1;
	do
		perm[i]++;
	while (arrsame(perm, i, perm[i]) || (perm[i] >= n && i--));
	if (perm[0] >= n)
		return 0;
	for (int num = 0, seat = i + 1; seat < k; num++)
		if (!arrsame(perm, i + 1, num))
			perm[seat++] = num;
	return 1;
}
int main() {
	int n, k;
	cout << "perm(n,k):" << endl;
	cin >> n >> k;
	if (n < k || k <= 0)
		return 0;
	int* perm = new int[k];
	for (int i = 0; i < k; i++)
		perm[i] = i;
	do
		for (int i = 0; i < k; cout << ((++i < k) ? ',' : '\n'))
			cout << perm[i] + 1;
	while (next_perm(perm, k, n));
	delete[] perm;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct prem {
	int len;
	vector<int> used, position;
	function<void(vector<int>&)> action;
	prem(int l = 0, function<void(vector<int>&)> a = [](vector<int>& position) {}) : len(l), used(l, -1), position(l), action(a) {}
	void run(int now = -1) {
		if (now == len - 1) {
			action(position);
			return;
		}
		int next = now + 1;
		for (int i = 0; i < len; i++) {
			if (used[i] == -1) {
				used[i] = next;
				position[next] = i;
				run(next);
				used[i] = -1;
			}
		}
	}
};
int main() {
	ios::sync_with_stdio(false), cin.tie(0);
	int len = 4;
	prem p(len, [&](vector<int>& p) {
		for (int i = 0; i < len; i++) {
			cout << p[i] << " ";
		}
		cout << endl;
	});
	p.run();
	return 0;
}

