以下代码基于路径压缩和按秩合并的并查集，时间复杂度 \Omicron(|E| \alpha (|V|))。

#include <bits/stdc++.h>

struct DSU {
    std::vector<int> fa, sz;
    DSU(int n = 0) : fa(n), sz(n, 1) {
        std::iota(fa.begin(), fa.end(), 0);
    }
    int Find(int x) { // 路径压缩
        while (x != fa[x])
            x = fa[x] = fa[fa[x]];
        return x;
    }
    bool Merge(int x, int y) { // 按秩合并
        x = Find(x), y = Find(y);
        if (x == y) return false; // 处于同一连通分量
        if (sz[x] > sz[y]) std::swap(x, y);
        fa[x] = y;
        sz[y] += sz[x];
        return true;
    }
}; // 并查集

int main() {
    int n, m; // 点数，边数
    std::cin >> n >> m;
    std::vector<std::tuple<int, int, int>> edge(m);
    // 边集，三元组分别表示边权和边的两个端点
    for (auto &[w, u, v] : edge)
        std::cin >> u >> v >> w;
    std::sort(edge.begin(), edge.end()); // 按边权升序排序
    DSU dsu(n); // 初始化并查集
    long long result = 0; // 最小生成树边权和
    for (auto &[w, u, v] : edge)
        if (dsu.Merge(u, v)) result += w;
        // 合并两个连通分量并统计答案
    std::cout << result << std::endl;
    return 0;
}

原始的带余除法算法可以视为是重复使用减法的过程。设要计算a除以b，则在a里面不断地扣除b，直到不能继续扣除（满足余数范围）为止。以a、b都是正整数，余数范围为\{0, 1, \dots , b - 1\}的除法为例，伪代码如下：

function Division(a, b)
    q ← 0; r ← a; 
     while r >= b do
        r ← r - b;
        q ← q + 1;
     end while
     return q, r;

这样的算法复杂度是\frac{a}{b}的级别。

更为优化的算法是使用二进制以及二分法的结合。算法大致分为两个部分：首先用不断倍增的方式找出一个a所属的区间，然后用二分法不断收窄区间，直到将a限制在一个长度为b的区间为止。举例来说，要计算237除以9，可以首先列出如下表格：

0
1
2
3
4
5

1
2
4
8
16
32

9
18
36
72
144
288

也就是从小到大逐个列出2的幂次与9的乘积，直到超过237为止。其中，24 × 9 = 144 是小于等于237的最大数，之后的288就比237更大了。接下来反过来利用2的幂次与9的乘积来计算237除以9。过程如下：

设q=16，p=32；

237介于144与288之间，而144和288的平均数是216，比237小，令q = \frac{16 + 32}{2} = 24，p=32；

216和288的平均数是252，比237大，令q=24，p = \frac{24 + 32}{2} = 28；

216和252的平均数是234，比237小，令q = \frac{24 + 28}{2} = 26，p=28；

234和252的平均数是243，比237大，令q=26，p = \frac{26 + 28}{2} = 27；

最后得到q的值为26，这就是237除以9的商，237减去234剩余的3就是余数。伪代码如下：

function QuickDivision(a, b)
     counter ← 0; power ← 1; mid ← 0; appr ← 0;
     //找到2的幂次与除数b的乘积中比被除数a大的最小数对应的幂次
     while power * b <= a do
        counter ← counter + 1;
        power ← power * 2 ;
     end while
     p ← power; q ← power / 2;
     //p和q乘以b以後分别是a的上界和下界，以下用二分法不断收窄上下界，直到上下界之差等于b（即p与q之差等于1）为止
     for k from 1 to counter - 1 do
        //计算上下界的平均值
        comp ← (p + q) / 2;
        mid ← comp * b;
        //如果平均值小于等于a，则调高下界，同时记录平均值，否则调低上界
        if mid <= a then
           appr ← mid;
           q ← comp;
        else
           p ← comp;
        end if
     end for 
     //结束后q乘以b的积就是小于等于a的b的倍数中最大的，这说明q就是商；appr是最後一个小于等于a的平均值，所以它和a的差就是余数
     r ← a - appr; 
     return q, r;

以上的算法的复杂度在\log_2\left(\frac{a}{b}\right)级别，当\frac{a}{b}较大时，远远比原始的算法快捷。

